#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
set -eu

# Do not replace a previous report with an empty one when the source log is
# unavailable. SKU-9 is a catalog SKU and must be reported even without a
# movement record.
[ -r movements.log ] || {
    echo "stock.sh: movements.log is required" >&2
    exit 1
}

awk '
    BEGIN { net["SKU-9"] = 0 }
    {
        net[$1] += ($2 == "receipt" ? $3 : -$3)
    }
    END {
        for (sku in net)
            print sku, net[sku]
    }
' movements.log | sort > stock.txt
